import React, { useState, useEffect } from 'react';
import { getExamData, deleteUserExamData, updateExamData, fetchExamNames, fetchDurationOptions } from '../services/api';

const ExamData = () => {
  const [examDataList, setExamDataList] = useState([]);
  const [filteredExamData, setFilteredExamData] = useState([]);
  const [errorMessage, setErrorMessage] = useState('');
  const [selectedFranchise, setSelectedFranchise] = useState('');
  const [editingExamId, setEditingExamId] = useState(null);
  const [editingData, setEditingData] = useState({
    name: '',
    examName: '',
    date: '',
    durationInMinutes: '',
    status: '',
  });
  const [examNames, setExamNames] = useState([]); // State for exam names
  const [durations, setDurations] = useState([]); // State for durations

  useEffect(() => {
    const fetchExamData = async () => {
      try {
        const response = await getExamData();
        if (response && response.length > 0) {
          const allExamData = response.flatMap(franchise =>
            (franchise.examData || []).map(exam => ({
              franchiseId: franchise._id,
              franchiseName: franchise.name,
              location: franchise.location,
              name: exam.name,
              examName: exam.examName,
              date: exam.date ? new Date(exam.date).toISOString().split('T')[0] : '',
              duration: exam.durationInMinutes,
              status: exam.status,
              examId: exam._id,
            }))
          );
          setExamDataList(allExamData);
          setFilteredExamData(allExamData);
        } else {
          setErrorMessage('No exam data available for your franchises.');
        }
      } catch (error) {
        console.error('Error fetching exam data:', error);
        setErrorMessage('Unable to retrieve exam data. Please try again later.');
      }
    };

    const fetchExamNamesAndDurations = async () => {
      try {
        const [examNamesResponse, durationsResponse] = await Promise.all([fetchExamNames(), fetchDurationOptions()]);
        
        if (examNamesResponse) {
          setExamNames(examNamesResponse); // Set the fetched exam names
        }
        if (durationsResponse) {
          setDurations(durationsResponse); // Set the fetched durations
        }
      } catch (error) {
        console.error('Error fetching exam names or durations:', error);
        setErrorMessage('Unable to fetch exam names or durations.');
      }
    };

    fetchExamData();
    fetchExamNamesAndDurations();
  }, []);

  // Filter exam data based on selected franchise
  const handleFranchiseFilterChange = (e) => {
    const selectedFranchise = e.target.value;
    setSelectedFranchise(selectedFranchise);

    const filteredData = examDataList.filter(exam =>
      exam.franchiseId === selectedFranchise || !selectedFranchise
    );
    setFilteredExamData(filteredData);
  };

  // Handle form changes
  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setEditingData((prevData) => ({
      ...prevData,
      [name]: value,
    }));
  };

  // Handle edit button click
  const handleEditClick = (examId, data) => {
    setEditingExamId(examId);
    setEditingData(data);
  };

  // Handle form submission for updating exam data
  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const updatedData = await updateExamData(editingData.franchiseId, editingExamId, editingData);
      const updatedExamDataList = examDataList.map((exam) =>
        exam.examId === editingExamId ? { ...exam, ...updatedData } : exam
      );
      setExamDataList(updatedExamDataList);
      setFilteredExamData(updatedExamDataList);
      setEditingExamId(null);
      setEditingData({
        name: '',
        examName: '',
        date: '',
        durationInMinutes: '',
        status: '',
      });
    } catch (error) {
      console.error('Error updating exam data:', error);
    }
  };

  return (
    <div>
      <h1>Exam Data</h1>
      {errorMessage && <div>{errorMessage}</div>}

      {/* Franchise Filter */}
      <select onChange={handleFranchiseFilterChange} value={selectedFranchise}>
        <option value="">All Franchises</option>
        {examDataList.map((exam) => (
          <option key={exam.franchiseId} value={exam.franchiseId}>
            {exam.franchiseName} - {exam.location}
          </option>
        ))}
      </select>

      <table>
        <thead>
          <tr>
            <th>Exam Name</th>
            <th>Date</th>
            <th>Duration</th>
            <th>Status</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {filteredExamData.map((exam) => (
            <tr key={exam.examId}>
              <td>{exam.examName}</td>
              <td>{exam.date}</td>
              <td>{exam.duration}</td>
              <td>{exam.status}</td>
              <td>
                <button onClick={() => handleEditClick(exam.examId, exam)}>Edit</button>
                <button onClick={async () => {
                  await deleteUserExamData(exam.franchiseId, exam.examId);
                  setExamDataList(prevData => prevData.filter(item => item.examId !== exam.examId));
                  setFilteredExamData(prevData => prevData.filter(item => item.examId !== exam.examId));
                }}>
                  Delete
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>

      {/* Edit Form */}
      {editingExamId && (
        <form onSubmit={handleSubmit}>
          <h2>Edit Exam Data</h2>
          <label>
            Name:
            <input
              type="text"
              name="name"
              value={editingData.name}
              onChange={handleInputChange}
            />
          </label>
          <label>
            Exam Name:
            <select
              name="examName"
              value={editingData.examName}
              onChange={handleInputChange}
            >
              {examNames.map((exam) => (
                <option key={exam} value={exam}>
                  {exam}
                </option>
              ))}
            </select>
          </label>
          <label>
            Date:
            <input
              type="date"
              name="date"
              value={editingData.date}
              onChange={handleInputChange}
            />
          </label>
          <label>
            Duration:
            <select
              name="durationInMinutes"
              value={editingData.durationInMinutes}
              onChange={handleInputChange}
            >
              {durations.map((duration) => (
                <option key={duration} value={duration}>
                  {duration} mins
                </option>
              ))}
            </select>
          </label>
          <label>
            Status:
            <select
              name="status"
              value={editingData.status}
              onChange={handleInputChange}
            >
              <option value="completed">Completed</option>
              <option value="inprogress">In Progress</option>
              <option value="absent">Absent</option>
            </select>
          </label>
          <button type="submit">Update</button>
        </form>
      )}
    </div>
  );
};

export default ExamData;
